// Component catalogue of the app (plan 114-01, D-MH-01…03): the neutral catalogue of the harness (types built from layers, materials,
// type GUIDs), known to the house builder without a running harness.
//
// Source: katalog.json next to this file — GENERATED by `python -m harness.bauteilkatalog app-export` (harness/harness/bauteilkatalog/
// app_export.py) from the builder elmonkey-core, never edited by hand; a harness test compares it byte for byte with a fresh export. The
// building logic (build plan, stud walls, IFC parts) stays in the harness; this module only READS the data.
//
// Loading: the JSON (~74 KB, ~8 KB gzip) is loaded LAZILY with ladeKatalog() (dynamic import → own chunk). Reason: materialien.js and
// aufbauten.js sit in the entry chunk, which has no room for it (size budget, scripts/groessen-budget.mjs). Until the catalogue is loaded
// every lookup answers null / [] — a wall that names a catalogue type then keeps its old build-up (composite, class, thickness). The first
// lookup of a catalogue reference starts the load (ensureLoad); a view that shows catalogue walls awaits ladeKatalog() before it renders
// (BIM studio, plan 114-03).
//
// Identity (D-MH-03): a type's IFC GUID is `typ_guid` from the export — made ONLY in the harness (guids.typ_guid: uuid5 in our own
// namespace, 22 characters). There is no uuid5 re-implementation here; runtime types bring their GUID with the harness proposal (114-04).
//
// Units: the catalogue states thicknesses in METRES (dicke_m); katalogAufbau() converts to the MILLIMETRES of `skins` (the format of the
// project build-ups `aufbauten_layer`, aufbauten.js).
//
// In:  katalog.json (lazy). Out: ladeKatalog(), setzeKatalog(), katalogGeladen(), katalogTypen(), katalogTyp(), katalogAufbau(),
//      katalogTypGuid(), katalogBaustoff(), katalogMaterial(), katalogMaterialien(), constants KATALOG_PRAEFIX, KATALOG_GRUPPE.
//      No imports of other app modules (materialien.js imports THIS module, so the dependency points one way).

/**
 * One layer of a catalogue type (outside → inside).
 * @typedef {object} KatalogSchicht
 * @property {string} baustoff        material key of the catalogue (`kalksandstein-635`)
 * @property {number} dicke_m         thickness in m
 * @property {string|null} rolle      IFC4 IfcMaterialLayer category ("LoadBearing" | "Insulation" | "Outer finish" | "Inner finish") or null
 * @property {object} [staenderwerk]  stud frame of the layer (profile, centre distance in m, …) — the harness decomposes it into parts
 */

/**
 * One catalogue type (base stock).
 * @typedef {object} KatalogTyp
 * @property {string} schluessel       key, a–z 0–9 and "-"
 * @property {number} version          version ≥ 1
 * @property {boolean} rohling         true = blank type (template without build-up)
 * @property {string} klasse           IFC4 class (IfcWall, IfcSlab, IfcCovering, IfcDoor, IfcWindow)
 * @property {string|null} predefined_type IFC PredefinedType
 * @property {string} kurzname         short name (display)
 * @property {string} langname         long name with the layers (display)
 * @property {number|null} dicke_m     total thickness in m, null for doors/windows
 * @property {string|null} din276      cost group DIN 276 (3 digits) or null
 * @property {Record<string, any>} pset_common  Pset_*Common values (IsExternal, LoadBearing, …)
 * @property {KatalogSchicht[]} schichten layers outside → inside (empty for doors/windows)
 * @property {{breite_m: number|null, hoehe_m: number|null, oeffnungsart: string|null}} [oeffnung] doors/windows: size in m, operation type
 * @property {string} typ_guid         IFC GlobalId of the type (22 characters), made by the harness
 */

/**
 * One catalogue material.
 * @typedef {object} KatalogBaustoff
 * @property {string} schluessel
 * @property {string} name                 full name (data, not a UI string)
 * @property {string|null} kurz            short name or null
 * @property {string} werkstoffklasse      material class of the catalogue (`mauerwerk`, `daemmung_hart`, …)
 * @property {string|null} farbe           display colour (hex)
 * @property {number|null} verschneidungsprioritaet intersection priority 0-999
 * @property {{lambda_W_mK?: number, dichte_kg_m3?: number, waermekapazitaet_J_kgK?: number, graue_energie_MJ_kg?: number, co2_kg_kg?: number}} kennwerte
 *   λ in W/(m·K), density in kg/m³, heat capacity in J/(kg·K), embodied energy in MJ/kg, CO₂ in kg/kg
 */

/** Id prefix of catalogue materials in the material lookup (`kat:<schluessel>`, D-MH-02) — the 22 app ids never start with it. */
export const KATALOG_PRAEFIX = "kat:";

/** Group name of the catalogue materials (German UI string = i18n key, English in i18nTeile/bauteilkatalog-114.js). */
export const KATALOG_GRUPPE = "Katalog";

/**
 * Catalogue material class → app material category (materialien.js `kategorie`). The category drives the layer-function and priority
 * PROPOSALS of aufbauten.js for layers whose type states no role. [ASSUMED] grouping by construction behaviour, not a norm: solid mineral
 * classes (masonry, concrete, screed, natural stone) "Massiv"; boards incl. ceramic tiles "Platte"; membranes, plastics and textiles "Bahn";
 * metal, glass, roof covering, soil and pseudo-materials "Sonstig" (never a core proposal, priority proposal 500). Way to a proven value:
 * the user confirms the grouping per class, or the catalogue gets an explicit app category.
 * @type {Readonly<Record<string, string>>}
 */
const KATEGORIE_VON_KLASSE = Object.freeze({
  mauerwerk: "Massiv", stahlbeton: "Massiv", beton: "Massiv", leichtbeton: "Massiv", naturstein: "Massiv", estrich: "Massiv",
  holz: "Holz", holzwerkstoff: "Platte", gipsplatte: "Platte", keramik: "Platte", putz: "Putz",
  daemmung_hart: "Dämmung", daemmung_weich: "Dämmung", bitumen: "Bahn", abdichtung: "Bahn", kunststoff: "Bahn", textil: "Bahn", luft: "Luft",
});

/**
 * Catalogue material class → hatch pattern of the layer-stack drawing (materialien.js `hatch`). [ASSUMED] nearest of the app's six
 * patterns (concrete, brick, block, insul, wood, none); the catalogue's own DIN 1356-1 hatching is not exported (the IFC of the harness
 * carries it).
 * @type {Readonly<Record<string, string>>}
 */
const SCHRAFFUR_VON_KLASSE = Object.freeze({
  stahlbeton: "concrete", beton: "concrete", leichtbeton: "concrete", estrich: "concrete", mauerwerk: "brick", naturstein: "block",
  holz: "wood", holzwerkstoff: "wood", daemmung_hart: "insul", daemmung_weich: "insul",
});

/**
 * Layer role of the catalogue (IFC4 IfcMaterialLayer.Category) → layer function of the app (aufbauten.js FUNKTIONEN). LoadBearing is the
 * core, finishes are claddings, insulation is "sonstig" (the same function aufbauten.js proposes for insulation). A layer without a role
 * gets no stated function — the app then PROPOSES one (marked as derived, D-BW-03).
 * @type {Readonly<Record<string, "kern"|"bekleidung"|"sonstig">>}
 */
const FUNKTION_VON_ROLLE = Object.freeze({ LoadBearing: "kern", "Outer finish": "bekleidung", "Inner finish": "bekleidung", Insulation: "sonstig" });

/** Colour of a catalogue material without a valid colour (slate, as erscheinung.js). */
const FARBE_OHNE = "#94a3b8";

/** @type {{typen: KatalogTyp[], baustoffe: KatalogBaustoff[], quelle?: string, inhalt_sha256?: string}|null} the loaded catalogue */
let daten = null;
/** @type {Map<string, Map<number, KatalogTyp>>} key → version → type */
let typNachSchluessel = new Map();
/** @type {Map<string, KatalogBaustoff>} */
let baustoffNachSchluessel = new Map();
/** @type {Map<string, import("../materialien.js").Material>} material records by app id `kat:<schluessel>` (built once per load) */
let materialNachId = new Map();
/** @type {Promise<boolean>|null} the running or finished load */
let laden = null;
/** true after a failed import: background lookups do not start it again (review 114-01: a render asking hundreds of times
 *  would retry and log every time); only an explicit ladeKatalog() call tries once more. */
let fehlgeschlagen = false;

/**
 * Hands catalogue data to the lookups (used by ladeKatalog(); tests may pass their own data). Idempotent per data object.
 * @param {{typen?: KatalogTyp[], baustoffe?: KatalogBaustoff[], quelle?: string, inhalt_sha256?: string}|null} d the parsed katalog.json,
 *   null clears the catalogue (lookups answer null again)
 * @returns {void} replaces the module-level maps
 */
export function setzeKatalog(d) {
  const typen = Array.isArray(d?.typen) ? d.typen : [];
  const baustoffe = Array.isArray(d?.baustoffe) ? d.baustoffe : [];
  daten = d ? { ...d, typen, baustoffe } : null;
  typNachSchluessel = new Map();
  for (const t of typen) {
    if (!typNachSchluessel.has(t.schluessel)) typNachSchluessel.set(t.schluessel, new Map());
    /** @type {Map<number, KatalogTyp>} */ (typNachSchluessel.get(t.schluessel)).set(Number(t.version) || 1, t);
  }
  baustoffNachSchluessel = new Map(baustoffe.map((b) => [b.schluessel, b]));
  materialNachId = new Map(baustoffe.map((b) => [KATALOG_PRAEFIX + b.schluessel, alsMaterial(b)]));
  if (!d) laden = null;
}

/**
 * Loads katalog.json once (dynamic import, own chunk) and hands it to the lookups. Safe to call often: later calls return the same promise.
 * @returns {Promise<boolean>} true when the catalogue is loaded; false when the import failed (the error is logged, lookups stay empty)
 */
export function ladeKatalog() {
  if (!laden) {
    fehlgeschlagen = false;
    laden = import("./katalog.json").then(
      (m) => { setzeKatalog(/** @type {any} */ (m).default ?? m); return true; },
      (e) => { console.error("Bauteilkatalog konnte nicht geladen werden:", e); laden = null; fehlgeschlagen = true; return false; },
    );
  }
  return laden;
}

/** @returns {boolean} true when the catalogue data is loaded (lookups answer) */
export function katalogGeladen() {
  return daten !== null;
}

/** Starts the load in the background on the first catalogue lookup (fire and forget; the caller still gets null this time). */
function ensureLoad() {
  if (!daten && !laden && !fehlgeschlagen) void ladeKatalog();
}

/**
 * Catalogue types, sorted by key and version (the order of the export).
 * @param {{klasse?: string, rohlinge?: boolean}} [filter] klasse: only this IFC class (e.g. "IfcWall"); rohlinge: include blank types
 *   (default false)
 * @returns {KatalogTyp[]} empty while the catalogue is not loaded
 */
export function katalogTypen(filter = {}) {
  ensureLoad();
  if (!daten) return [];
  return daten.typen.filter((t) => (!filter.klasse || t.klasse === filter.klasse) && (filter.rohlinge || !t.rohling));
}

/**
 * One type by reference: `schluessel` (highest version) or `schluessel@version` (exactly that version).
 * @param {string|null|undefined} ref type reference, e.g. "ks-wdvs-42-cm@1"
 * @returns {KatalogTyp|null} null for an empty or unknown reference, an unknown version, or while the catalogue is not loaded
 */
export function katalogTyp(ref) {
  if (typeof ref !== "string" || !ref.trim()) return null;
  ensureLoad();
  const [schluessel, v, ...rest] = ref.trim().split("@");
  const versionen = typNachSchluessel.get(schluessel);
  if (!versionen || rest.length) return null;
  if (v === undefined) return versionen.get(Math.max(...versionen.keys())) || null;
  if (!/^[1-9]\d*$/.test(v)) return null;
  return versionen.get(Number(v)) || null;
}

/**
 * IFC GlobalId of a catalogue type: the `typ_guid` of the export (the harness is the one place where type GUIDs are made, D-MH-03).
 * @param {KatalogTyp|string|null|undefined} typ the type, or a reference resolved with katalogTyp()
 * @returns {string|null} 22 characters of the IFC base-64 alphabet, null for an unknown type
 */
export function katalogTypGuid(typ) {
  const t = typeof typ === "string" ? katalogTyp(typ) : typ;
  return typeof t?.typ_guid === "string" && t.typ_guid.length === 22 ? t.typ_guid : null;
}

/**
 * One catalogue material by key.
 * @param {string|null|undefined} schluessel catalogue key (`kalksandstein-635`)
 * @returns {KatalogBaustoff|null}
 */
export function katalogBaustoff(schluessel) {
  if (!schluessel) return null;
  ensureLoad();
  return baustoffNachSchluessel.get(String(schluessel)) || null;
}

/**
 * Material record of the app (materialien.js `Material`) for a catalogue material: id `kat:<schluessel>`, group "Katalog", category and
 * hatch mapped from the material class, λ and density from the catalogue values. μ is unknown in the catalogue (null), and a λ of 0
 * (pseudo-materials of the source, e.g. priority placeholders) is no conductivity (null).
 * @param {KatalogBaustoff} b
 * @returns {import("../materialien.js").Material}
 */
function alsMaterial(b) {
  const lam = Number(b.kennwerte?.lambda_W_mK);
  const dichte = Number(b.kennwerte?.dichte_kg_m3);
  return {
    id: KATALOG_PRAEFIX + b.schluessel, name: b.name || b.schluessel, kategorie: KATEGORIE_VON_KLASSE[b.werkstoffklasse] || "Sonstig",
    lambda: lam > 0 ? lam : null, mu: null, schicht: null, ...(dichte > 0 ? { dichte } : {}),
    color: typeof b.farbe === "string" && b.farbe.startsWith("#") ? b.farbe : FARBE_OHNE, hatch: SCHRAFFUR_VON_KLASSE[b.werkstoffklasse] || "none",
    gruppe: KATALOG_GRUPPE, schluessel: b.schluessel, kurz: b.kurz || null, werkstoffklasse: b.werkstoffklasse,
    ...(Number.isInteger(b.verschneidungsprioritaet) ? { prioritaet: b.verschneidungsprioritaet } : {}),
  };
}

/**
 * The material record of a catalogue material id (`kat:<schluessel>`), as materialById() answers it.
 * @param {string|null|undefined} id app material id
 * @returns {import("../materialien.js").Material|null} null for ids without the prefix, unknown keys, or while the catalogue is not loaded
 */
export function katalogMaterial(id) {
  if (typeof id !== "string" || !id.startsWith(KATALOG_PRAEFIX)) return null;
  ensureLoad();
  return materialNachId.get(id) || null;
}

/**
 * All catalogue materials as app material records (group "Katalog"), sorted by key.
 * @returns {import("../materialien.js").Material[]} empty while the catalogue is not loaded
 */
export function katalogMaterialien() {
  ensureLoad();
  return [...materialNachId.values()];
}

/**
 * Build-up of a catalogue type in the format of the project build-ups (`aufbauten_layer` entries, aufbauten.js Skin): thickness in MM,
 * material `kat:<baustoff>`, function from the layer role (no role → no stated function, the app proposes one), intersection priority
 * from the material's catalogue value (0-999), colour and hatch of the material.
 * @param {KatalogTyp|null|undefined} typ catalogue type (katalogTyp())
 * A layer of thickness 0 (a membrane the catalogue states without thickness, e.g. a foil) is left out — a skin needs a positive thickness,
 * the same rule as the project build-ups (normalisiereProjektAufbauten); the total thickness is unchanged by it.
 * @returns {{id: string, name: string, skins: import("../aufbauten.js").Skin[]}|null} id `kat:<schluessel>@<version>`; null for a type
 *   without layers of positive thickness (doors, windows, blanks)
 */
export function katalogAufbau(typ) {
  if (!typ || !Array.isArray(typ.schichten) || !typ.schichten.length) return null;
  /** @type {import("../aufbauten.js").Skin[]} */
  const skins = [];
  for (const s of typ.schichten) {
    const d = Number(s?.dicke_m);
    if (!(d > 0)) continue;
    const b = baustoffNachSchluessel.get(s.baustoff);
    const m = materialNachId.get(KATALOG_PRAEFIX + s.baustoff);
    /** @type {import("../aufbauten.js").Skin} */
    // m → mm, rounded to 1 µm against float noise (0.0125 m → 12.5 mm)
    const skin = { name: b?.kurz || b?.name || s.baustoff, material: KATALOG_PRAEFIX + s.baustoff, thickness: Math.round(d * 1e6) / 1e3,
      color: m?.color || FARBE_OHNE, hatch: m?.hatch || "none" };
    const f = s.rolle ? FUNKTION_VON_ROLLE[s.rolle] : undefined;
    if (f) skin.funktion = f;
    if (Number.isInteger(b?.verschneidungsprioritaet)) skin.prioritaet = /** @type {number} */ (b?.verschneidungsprioritaet);
    skins.push(skin);
  }
  if (!skins.length) return null;
  return { id: `${KATALOG_PRAEFIX}${typ.schluessel}@${typ.version}`, name: typ.kurzname || typ.schluessel, skins };
}
